<?php
declare(strict_types=1);
use DigiForge\Research\DesignFactoryRepository as Factory;
use DigiForge\Research\CommercialResearchRepository;
final class DesignFactoryWorkflowTest extends WP_UnitTestCase
{
 protected function setUp():void {parent::setUp();self::assertTrue(class_exists(Factory::class),'Approved-concept design factory required');$id=self::factory()->user->create();$u=new WP_User($id);foreach(['manage_digiforge_pod','manage_digiforge_research']as $cap)$u->add_cap($cap);wp_set_current_user($id);}
 private function selected():array {$f=json_decode(file_get_contents(__DIR__.'/../fixtures/research/commercial-research.json'),true);$r=new CommercialResearchRepository();$a=$r->create($f['research']);$b=$r->importResponse('personalized_pod',$a['hash'],json_encode($f['response']),['method'=>'manual','provider'=>'human','model'=>'none','response_id'=>'test','generated_at'=>'2026-11-03T12:00:00Z']);return $r->select('personalized_pod',$b['hash'],1);}
 private function choices():array {return ['layout_notes'=>'Original paired paths outside native names','typography'=>'Licensed serif native text','font_license_reference'=>'Human license evidence','palette'=>['#123456','#ffffff'],'native_regions'=>[['name'=>'names','kind'=>'text','x'=>500,'y'=>400,'width'=>1400,'height'=>300]],'asset_requirements'=>['Original fixed geometry, separate native text']];}
 private function approved():array {$s=$this->selected();return (new Factory())->approveConcept('personalized_pod',$s['hash'],['sources_reviewed'=>true,'buyer_intent_reviewed'=>true,'gifting_occasion_reviewed'=>true,'note'=>'Reviewed synthetic source-linked concept for test only']);}
 private function prepared():array {$a=$this->approved();return (new Factory())->prepare('personalized_pod',$a['hash'],'fl03_mug_11oz',$this->choices());}
 private function payload():array {return ['svg'=>file_get_contents(__DIR__.'/../fixtures/design-factory/mug-original.svg'),'raster_uploads'=>[],'rights_note'=>'Original test geometry; font evidence recorded','source_note'=>'Manual original SVG import, illustrative only'];}
 public function testMissingSourceApprovalCannotGenerateSpecification():void {$s=$this->selected();$r=new Factory();self::assertWPError($r->prepare('personalized_pod',$s['hash'],'fl03_mug_11oz',$this->choices()));self::assertWPError($r->approveConcept('personalized_pod',$s['hash'],['sources_reviewed'=>false,'buyer_intent_reviewed'=>true,'gifting_occasion_reviewed'=>true,'note'=>'Not reviewed']));}
 public function testApprovedConceptAndSvgHaveImmutableReviewableHandoff():void {
  $r=new Factory();$p=$this->prepared();self::assertSame('SPEC_READY',$p['record']['kind']);$a=$r->importArtwork('personalized_pod',$p['hash'],$this->payload());self::assertIsArray($a);self::assertSame('ASSET_READY',$a['record']['kind']);self::assertWPError($r->handoff('personalized_pod',$a['hash']));
  $criteria=array_fill_keys(\DigiForge\Research\DesignFactoryContract::REVIEW_CRITERIA,true);$bad=$criteria;$bad['visual_distinctiveness']=false;self::assertWPError($r->review('personalized_pod',$a['hash'],'APPROVE',$bad,'Needs distinctiveness review'));
  $v=$r->review('personalized_pod',$a['hash'],'APPROVE',$criteria,'Reviewed exact original fixed graphic and native reservations');self::assertIsArray($v);self::assertSame('HUMAN_APPROVED',$v['review_state']);self::assertSame(get_current_user_id(),$v['record']['created_by']);
  $out=$r->handoff('personalized_pod',$v['hash']);self::assertSame('HUMAN_APPROVED',$out['artwork']['approval']['state']);self::assertSame($out['artwork']['version_hash'],$out['artwork']['approval']['evidence_hash']);self::assertSame(['names'],$out['artwork']['record']['input']['artwork']['native_layers']);self::assertNull($out['design_metadata']['geometry']['supplier_bleed_px']);self::assertTrue($out['artwork']['release_hold']);self::assertSame($criteria,$out['design_metadata']['human_review']['criteria']);self::assertSame($v['hash'],$out['design_metadata']['human_review']['review_hash']);
  self::assertWPError($r->review('personalized_pod',$a['hash'],'REJECT',$criteria,'Cannot overwrite decision'));
  $revision=$r->revise('personalized_pod',$v['hash'],'Try a different original path');self::assertSame('SPEC_READY',$revision['record']['kind']);self::assertNull($revision['record']['asset']);self::assertSame('HUMAN_APPROVED',$r->read('personalized_pod',$v['hash'])['review_state']);self::assertCount(5,$r->history('personalized_pod',$revision['hash']));
 }
 public function testRejectionRequiresFreshAssetAndPreservesOldVersion():void {$r=new Factory();$p=$this->prepared();$a=$r->importArtwork('personalized_pod',$p['hash'],$this->payload());$criteria=array_fill_keys(\DigiForge\Research\DesignFactoryContract::REVIEW_CRITERIA,false);$v=$r->review('personalized_pod',$a['hash'],'REJECT',$criteria,'Composition needs revision');self::assertSame('HUMAN_REJECTED',$v['review_state']);self::assertWPError($r->handoff('personalized_pod',$v['hash']));self::assertSame($a['record']['asset'],$r->read('personalized_pod',$a['hash'])['record']['asset']);}
 public function testCrossShopAndUnauthorizedActionsDenied():void {$r=new Factory();$p=$this->prepared();foreach(['digital','standard_pod','all','jewelry']as $shop){self::assertWPError($r->read($shop,$p['hash']));self::assertWPError($r->importArtwork($shop,$p['hash'],$this->payload()));self::assertWPError($r->generate($shop,$p['hash']));}wp_set_current_user(0);self::assertWPError($r->read('personalized_pod',$p['hash']));self::assertWPError($r->review('personalized_pod',$p['hash'],'APPROVE',[],'Unauthorized'));}
 public function testNoProviderDispatchOrHttpUnderStopAll():void {$p=$this->prepared();$provider=new class implements \DigiForge\Research\DesignGenerationProvider {public int $calls=0;public function status():array{return ['available'=>true];}public function generate(array $spec,string $attemptKey):array|WP_Error {++$this->calls;throw new RuntimeException('Must not run');}};$r=new Factory($provider);$calls=0;$deny=static function()use(&$calls){++$calls;return new WP_Error('no_http','Denied');};add_filter('pre_http_request',$deny);try{self::assertWPError($r->generate('personalized_pod',$p['hash']));self::assertSame(0,$provider->calls);self::assertSame(0,$calls);}finally{remove_filter('pre_http_request',$deny);}}
 public function testUnavailableProviderAndUnsafeImportsFailClosed():void {$p=$this->prepared();$r=new Factory();self::assertFalse($r->providerStatus()['available']);$bad=$this->payload();$bad['svg']='';self::assertWPError($r->importArtwork('personalized_pod',$p['hash'],$bad));$bad=$this->payload();$bad['raster_uploads']=[['mime_type'=>'image/jpeg','base64'=>base64_encode('not an image')]];self::assertWPError($r->importArtwork('personalized_pod',$p['hash'],$bad));}
 public function testExistingPortalActionExposesApprovedConceptFactory():void {
  self::assertTrue(class_exists(\DigiForge\Portal\DesignFactoryPanel::class),'Design factory portal panel required');$s=$this->selected();$_GET['df_research_version']=$s['hash'];ob_start();(new \DigiForge\Portal\CommercialResearchPanel())->render('personalized_pod');$html=ob_get_clean();unset($_GET['df_research_version']);self::assertStringContainsString('Approve source-linked concept',$html);self::assertStringContainsString('name="sources_reviewed"',$html);
  $panel=new \DigiForge\Portal\CommercialResearchPanel();$a=$panel->process(['operation'=>'design_approve_concept','shop_key'=>'personalized_pod','workflow_hash'=>$s['hash'],'sources_reviewed'=>'1','buyer_intent_reviewed'=>'1','gifting_occasion_reviewed'=>'1','note'=>'Human source and recipient review']);self::assertIsArray($a);self::assertSame($s['hash'],$a['hash']);self::assertArrayHasKey('design_factory_hash',$a);
 }
 private function png():string {$chunk=static fn($t,$d)=>pack('N',strlen($d)).$t.$d.hash('crc32b',$t.$d,true);return "\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',2475,1155,8,2,0,0,0)).$chunk('pHYs',pack('NNC',11811,11811,1)).$chunk('IDAT',gzcompress(str_repeat("\0".str_repeat("\xff",2475*3),1155))).$chunk('IEND','');}
 public function testRasterReferencesValidateBytesScopeAndTampering():void {
  $r=new Factory();$p=$this->prepared();$payload=$this->payload();$bytes=$this->png();$payload['raster_uploads']=[['mime_type'=>'image/png','base64'=>base64_encode($bytes)]];$a=$r->importArtwork('personalized_pod',$p['hash'],$payload);self::assertIsArray($a);$ref=$a['record']['asset']['raster_references'][0];self::assertFalse($ref['editable']);self::assertSame(hash('sha256',$bytes),$ref['sha256']);$saved=$r->raster('personalized_pod',$a['hash'],$ref['reference']);self::assertSame($bytes,base64_decode($saved['base64']));self::assertWPError($r->raster('digital',$a['hash'],$ref['reference']));self::assertWPError($r->raster('personalized_pod',$a['hash'],'file:///etc/passwd'));
  update_option('digiforge_design_personalized_pod_png_'.$ref['sha256'],'{}');self::assertWPError($r->read('personalized_pod',$a['hash']));
 }
 private function enableOnlyInTestDatabase():void {\DigiForge\Core\Settings::ensure_defaults();global $wpdb;foreach(['activation_authorized','automation_armed','ai','ai_activation_authorized','product_development','product_development_activation_authorized']as $key)$wpdb->update(\DigiForge\Database\Tables::settings(),['setting_value'=>'true'],['setting_key'=>$key]);$wpdb->update(\DigiForge\Database\Tables::settings(),['setting_value'=>'false'],['setting_key'=>'stop_all']);wp_get_current_user()->add_cap('manage_digiforge_ai');}
 public function testProviderFailureHasNoAutomaticRetryOrFinishedArtwork():void {
  $p=$this->prepared();$this->enableOnlyInTestDatabase();$provider=new class implements \DigiForge\Research\DesignGenerationProvider {public int $calls=0;public function status():array{return ['available'=>true];}public function generate(array $spec,string $attemptKey):array|WP_Error {++$this->calls;throw new RuntimeException('Failed');}};$r=new Factory($provider);self::assertWPError($r->generate('personalized_pod',$p['hash']));self::assertWPError($r->generate('personalized_pod',$p['hash']));self::assertSame(1,$provider->calls);self::assertNull($r->read('personalized_pod',$p['hash'])['record']['asset']);
 }
 public function testMalformedAndRasterOnlyProviderOutputCannotBecomeEditableArtwork():void {
  $p=$this->prepared();$this->enableOnlyInTestDatabase();$provider=new class implements \DigiForge\Research\DesignGenerationProvider {public function status():array{return ['available'=>true];}public function generate(array $spec,string $attemptKey):array|WP_Error {return ['asset'=>['svg'=>'','raster_uploads'=>[],'rights_note'=>'Model claim','source_note'=>'Raster only'], 'provenance'=>['provider'=>'fake','model'=>'fake','response_id'=>'fake','generated_at'=>'2026-11-03T12:00:00Z']];}};$r=new Factory($provider);self::assertWPError($r->generate('personalized_pod',$p['hash']));self::assertWPError($r->handoff('personalized_pod',$p['hash']));
 }
 public function testReviewIntentWriteFailureCannotApproveAndDecisionFailureIsInspectable():void {
  $r=new Factory();$p=$this->prepared();$a=$r->importArtwork('personalized_pod',$p['hash'],$this->payload());$criteria=array_fill_keys(\DigiForge\Research\DesignFactoryContract::REVIEW_CRITERIA,true);
  $intentFault=static fn($query)=>str_contains($query,'INSERT INTO')&&str_contains($query,'digiforge_design_personalized_pod_version_')?'SELECT 1 WHERE 0=1':$query;add_filter('query',$intentFault);try {self::assertWPError($r->review('personalized_pod',$a['hash'],'APPROVE',$criteria,'Rationale before approval'));}finally{remove_filter('query',$intentFault);}self::assertNull($r->read('personalized_pod',$a['hash'])['review_state']);
  $decisionFault=static fn($query)=>str_contains($query,'INSERT INTO')&&str_contains($query,'digiforge_opportunity_personalized_pod_')&&str_contains($query,'_decision')?'SELECT 1 WHERE 0=1':$query;add_filter('query',$decisionFault);try {$result=$r->review('personalized_pod',$a['hash'],'APPROVE',$criteria,'Preserved rationale before uncertain Day1 approval');self::assertWPError($result);}finally{remove_filter('query',$decisionFault);}
  $intent=$r->read('personalized_pod',$result->get_error_data()['design_factory_hash']);self::assertSame('APPROVAL_UNCONFIRMED',$intent['review_state']);self::assertSame('Preserved rationale before uncertain Day1 approval',$intent['record']['note']);self::assertWPError($r->handoff('personalized_pod',$intent['hash']));
 }
 public function testSelectedConceptCannotBypassFactoryThroughLegacyIntake():void {$s=$this->selected();$panel=new \DigiForge\Portal\CommercialResearchPanel();$result=$panel->process(['operation'=>'artwork','shop_key'=>'personalized_pod','workflow_hash'=>$s['hash'],'svg'=>file_get_contents(__DIR__.'/../fixtures/design-factory/mug-original.svg'),'width_px'=>'2475','height_px'=>'1155','native_layers'=>'names','rights_note'=>'Manual claim','review_note'=>'Manual claim','originality_reviewed'=>'1','licensing_reviewed'=>'1','safe_area_reviewed'=>'1','font_license_reviewed'=>'1','mockup_reviewed'=>'1']);self::assertWPError($result);}
 public function testReviewReceiptFailureCannotPresentARecordedDecision():void {
  $r=new Factory();$p=$this->prepared();$a=$r->importArtwork('personalized_pod',$p['hash'],$this->payload());$criteria=array_fill_keys(\DigiForge\Research\DesignFactoryContract::REVIEW_CRITERIA,false);
  $fault=static fn($query)=>str_contains($query,'INSERT INTO')&&str_contains($query,'digiforge_design_personalized_pod_decision_')?'SELECT 1 WHERE 0=1':$query;add_filter('query',$fault);try {self::assertWPError($r->review('personalized_pod',$a['hash'],'REJECT',$criteria,'Decision receipt unavailable'));}finally{remove_filter('query',$fault);}
  global $wpdb;$raws=$wpdb->get_col("SELECT option_value FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_design_personalized_pod_version_%'");$found=null;foreach($raws as $raw){$record=json_decode($raw,true);if(($record['kind']??null)==='REVIEW_INTENT'&&($record['parent_hash']??null)===$a['hash'])$found=hash('sha256',$raw);}self::assertIsString($found);self::assertSame('REVIEW_INTENT_UNCONFIRMED',$r->read('personalized_pod',$found)['review_state']);self::assertNull($r->read('personalized_pod',$a['hash'])['review_state']);
 }
}
